package pl.hubert.liberumveto.api.config;

import io.swagger.v3.oas.models.OpenAPI;
import io.swagger.v3.oas.models.info.Info;
import io.swagger.v3.oas.models.info.License;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * The top of the OpenAPI document. Endpoints, parameters and schemas are generated by springdoc
 * from the controllers and DTO records; this bean only adds the general description.
 */
@Configuration
public class OpenApiConfig {

    @Bean
    OpenAPI liberumVetoOpenApi() {
        return new OpenAPI().info(new Info()
                .title("Liberum Veto API")
                .version("v1")
                .description("""
                        REST API of a turn-based game about the 17th-century Polish-Lithuanian Sejm.
                        A turn: PUT selected-bill (the magnates bribe right away) → POST bribes (any number)
                        → POST votes. Errors are returned as application/problem+json (RFC 9457);
                        the `detail` field is in Polish and meant for the player.""")
                .license(new License().name("MIT")));
    }
}
